CREATE POLICY "topic sources own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'topic-sources' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "topic sources own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'topic-sources' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "topic sources own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'topic-sources' AND (storage.foldername(name))[1] = auth.uid()::text);